#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define D(U) texture(iChannel3,(U)/R)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec2 norm (vec2 v){
    if (length(v) == 0.) return vec2(0);
    else return normalize(v);
}
vec4 hash(vec4 p) {
                const vec4 k = vec4(0.1031, 0.11369, 0.13787, 0.16379); 
                p = fract(p * k);                                       
                p += dot(p, p.wxyz + k);                                
                p = fract((p.xxyz + p.yzww) * p.zyxw);                  
                return fract(sin(p) * 43758.5453);                      
            }
float ln (vec3 u, vec3 a, vec3 b) {
    return length(u-a-(b-a)*clamp(dot(u-a,b-a)/dot(b-a,b-a),0.,1.));
}

float scene (vec3 u) {
                u = 1.7*(u-.5*vec3(R,0))/R.y;
                u.y +=.7;
                float o = .2-.2*sign(length(u)-1.5);
                o += .1-.1*sign(abs(length(u)-1.3)-.05*(.5+.5*sign(sin(20.*atan(u.y,u.x)))));
                float d = 1e9;
                for (float i = 0.; i < 10.; i++) {
                    float d1 = ln(u,vec3(0),vec3(0,-.4*exp2(-.5*(i-1.)),0))-.1*exp2(-.35*i);
                   d = min(d,d1);
                    u.xz = abs(u.xz);
                    u.xy *= ei(-.5*exp2(-.15*i));
                    u.y -= .35*exp2(-.5*i);
                    o -= .1*exp(-100.*max(d1,0.));
                }
                return o;
            }

vec3 grad(vec3 p) {

       return vec3(
           scene(p+vec3(1,0,0))-scene(p-vec3(1,0,0)),
           scene(p+vec3(0,1,0))-scene(p-vec3(0,1,0))
       ,0);
   }  

   Main {
